package ebpf

// The embedded objects are generated by `make generate`, which runs this
// directive inside the pinned toolchain container (build/ebpf/Dockerfile).
// The generated pw_bpfel.go and pw_bpfel.o are committed, so building the
// agent needs neither clang nor LLVM. One little-endian object serves amd64
// and arm64: the programs use CO-RE and tp_btf only.

//go:generate go run github.com/cilium/ebpf/cmd/bpf2go -cc clang -target bpfel -tags linux -go-package ebpf pw bpf/collector.bpf.c -- -O2 -g -Wall -Werror -I bpf/headers
